// V3 Intelligence Engine
const SOURCE_WEIGHTS = {
  'techcrunch.com': 92, 'thehackernews.com': 90, 'arstechnica.com': 88,
  'technologyreview.com': 91, 'venturebeat.com': 86, 'theverge.com': 84,
  'news.ycombinator.com': 78, 'openai.com': 93, 'blog.google': 92, 'wired.com': 87, 'default': 70
};
const taxonomy = {
  aiTools: ['generative ai','genai','llm','agentic ai','chatgpt','gemini','copilot','openai','anthropic','claude'],
  aiHacks: ['jailbreak','prompt injection','ransomware','breach','cve','malware','phishing','zero-click','deepfake'],
  trendingAiSeo: ['ai overview','geo','semantic search','algorithm update','search generative experience'],
  devNews: ['vibe coding','developer tools','open source','framework','api','sdk','programming','github'],
  coreSecurity: ['zero-trust','soar','penetration testing','cyber attack','vulnerability','encryption','incident']
};
const SKIP_PATTERNS = [/sponsored/i,/advertisement/i,/partner content/i,/opinion:/i,/editorial:/i,/you won't believe/i,/shocking/i];
const CLICKBAIT = [/you won't believe/i,/shocking/i,/this one trick/i,/what happens next/i,/goes viral/i];

function norm(s='') { return s.toLowerCase().replace(/\s+/g,' ').trim(); }
function host(url='') { try { return new URL(url).hostname.replace(/^www\./,''); } catch { return 'default'; } }
function hoursSince(dateStr) {
  const d = new Date(dateStr); if (isNaN(d)) return 999;
  return (Date.now() - d.getTime()) / 3600000;
}
function detectCategory(text, matched) {
  const scores = {};
  for (const [cat, words] of Object.entries(taxonomy)) {
    scores[cat] = words.filter(w => text.includes(w)).length + matched.filter(m => taxonomy[cat].includes(m)).length * 2;
  }
  const best = Object.entries(scores).sort((a,b)=>b[1]-a[1])[0];
  return best && best[1] > 0 ? best[0] : 'aiTools';
}
function titleSimilarity(a, b) {
  const wa = new Set(norm(a).split(' ').filter(w=>w.length>3));
  const wb = new Set(norm(b).split(' ').filter(w=>w.length>3));
  if (!wa.size || !wb.size) return 0;
  let inter = 0; wa.forEach(w => { if (wb.has(w)) inter++; });
  return inter / Math.max(wa.size, wb.size);
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.postedUrls) staticData.postedUrls = [];
if (!staticData.postedTitles) staticData.postedTitles = [];
if (!staticData.analytics) staticData.analytics = [];

const allKeywords = Object.values(taxonomy).flat();
const items = $input.all();
const candidates = [];
const seenUrls = new Set();
const seenTitles = [];

for (const item of items) {
  const j = item.json;
  const title = (j.title || '').trim();
  const link = (j.link || j.url || '').trim();
  const summary = (j.contentSnippet || j.description || j.content || '').replace(/<[^>]+>/g,' ').trim();
  const searchStr = norm(title + ' ' + summary);
  if (!title || !link || summary.length < 80) continue;
  if (hoursSince(j.pubDate || j.isoDate || j.published) > 72) continue;
  if (SKIP_PATTERNS.some(p => p.test(title) || p.test(summary))) continue;
  if (staticData.postedUrls.includes(link)) continue;
  let dup = false;
  for (const t of seenTitles) { if (titleSimilarity(title, t) > 0.65) { dup = true; break; } }
  if (!dup) for (const t of staticData.postedTitles.slice(-40)) { if (titleSimilarity(title, t) > 0.65) { dup = true; break; } }
  if (dup || seenUrls.has(link)) continue;
  seenUrls.add(link); seenTitles.push(title);
  const matched = allKeywords.filter(k => searchStr.includes(k));
  if (!matched.length) continue;

  const h = host(link);
  const sourceKey = Object.keys(SOURCE_WEIGHTS).find(k => h.includes(k)) || 'default';
  const sourceTrust = SOURCE_WEIGHTS[sourceKey];
  const freshness = Math.max(0, 100 - hoursSince(j.pubDate || j.isoDate) * 3);
  const relevance = Math.min(100, matched.length * 14 + (searchStr.includes('ai') ? 10 : 0));
  const aiImpact = Math.min(100, matched.filter(k => taxonomy.aiTools.concat(taxonomy.trendingAiSeo).includes(k)).length * 18);
  const cyberImpact = Math.min(100, matched.filter(k => taxonomy.aiHacks.concat(taxonomy.coreSecurity).includes(k)).length * 20);
  const engagement = Math.min(100, (CLICKBAIT.some(p=>p.test(title)) ? 20 : 75) + (title.length < 90 ? 10 : 0));
  const uniqueness = Math.min(100, 85 + Math.min(15, matched.length * 2));
  const hours = hoursSince(j.pubDate || j.isoDate);
  const velocity = Math.min(100, Math.max(20, 100 - hours * 8));
  const breaking = hours < 6 && (/breaking|just in|emergency|alert/i.test(searchStr));

  const totalScore = relevance*0.2 + freshness*0.16 + sourceTrust*0.14 + aiImpact*0.13 + cyberImpact*0.12 + engagement*0.1 + uniqueness*0.07 + velocity*0.08 + (breaking ? 15 : 0);

  let imageUrl = j.imageUrl || j.enclosure?.url || null;
  if (!imageUrl && j.enclosure?.type?.startsWith('image')) imageUrl = j.enclosure.url;
  if (!imageUrl && (j.content || j.description)) {
    const m = String(j.content || j.description).match(/<img[^>]+src=[\"']([^\"']+)[\"']/i);
    if (m) imageUrl = m[1];
  }

  candidates.push({
    title, link, pubDate: j.pubDate || j.isoDate || j.published || '',
    summary: summary.slice(0, 900), matchedKeywords: matched, category: detectCategory(searchStr, matched),
    imageUrl, source: h, sourceTrust, breaking, isClickbait: CLICKBAIT.some(p=>p.test(title)),
    scores: { relevance, freshness, sourceTrust, aiImpact, cyberImpact, engagement, uniqueness, velocity, total: Math.round(totalScore*10)/10 }
  });
}

if (!candidates.length) {
  return [{ json: { found: false, reason: 'No qualifying RSS articles', triggerResearch: true, candidates: [], candidateIndex: 0 } }];
}

const categories = [...new Set(candidates.map(c => c.category))];
const rotationIndex = Math.floor(Date.now() / (1000*60*60*3)) % Math.max(categories.length, 1);
const preferredCategory = categories[rotationIndex] || categories[0];
const ranked = candidates
  .map(c => ({ ...c, totalScore: c.scores.total + (c.category === preferredCategory ? 8 : 0) - (c.isClickbait ? 25 : 0) }))
  .sort((a,b) => b.totalScore - a.totalScore);
const top = ranked.slice(0, 5);

return [{ json: {
  found: true, preferredCategory, candidates: top, winner: top[0], candidateIndex: 0,
  rejectedTitles: [], sourceMode: 'rss', triggerResearch: false,
  priority: top[0].breaking ? 'breaking' : 'scheduled'
}}];

const item = $input.first().json;
if (item.winner && Array.isArray(item.candidates)) return [{ json: item }];
const fromFilter = $('V3: Smart Filter Score & Rank').first()?.json;
return [{ json: fromFilter || item }];

