if (resp.candidates?.[0]?.content?.parts?.[0]?.text) raw = resp.candidates[0].content.parts[0].text;
let parsed = { worthPosting: true, confidence: 75, reason: 'Passed', breakingNews: false, clickbaitRisk: 'low', factCheck: 'unclear' };
try { const m = raw.match(/\{[\s\S]*\}/); if (m) parsed = { ...parsed, ...JSON.parse(m[0]) }; } catch (e) {}

const envelope = $('V3: Sync Candidate Envelope').first().json;
const winner = envelope.winner;
const approved = parsed.worthPosting !== false && parsed.clickbaitRisk !== 'high' && parsed.confidence >= 55;

return [{ json: {
  ...winner, aiGate: parsed, approved,
  envelope: { ...envelope, rejectedTitles: envelope.rejectedTitles || [] },
  sourceMode: envelope.sourceMode || 'rss', priority: envelope.priority || 'scheduled'
}}];

const j = $input.first().json;
const env = j.envelope || {};
const candidates = env.candidates || [];
let idx = env.candidateIndex ?? 0;
const rejectedTitles = [...(env.rejectedTitles || []), j.title].filter(Boolean);

if (env.sourceMode === 'rss' && idx < candidates.length - 1) {
  const nextIdx = idx + 1;
  return [{ json: {
    found: true, candidates, candidateIndex: nextIdx, winner: candidates[nextIdx],
    preferredCategory: env.preferredCategory, rejectedTitles, sourceMode: 'rss',
    fallbackAction: 'try_next_candidate', lastRejectionReason: j.aiGate?.reason || 'rejected',
    priority: candidates[nextIdx]?.breaking ? 'breaking' : env.priority
  }}];
}

return [{ json: {
  found: false, triggerResearch: true, fallbackAction: 'research',
  rejectedTitles, lastRejectionReason: j.aiGate?.reason || 'all candidates rejected',
  preferredCategory: env.preferredCategory || 'aiTools'
}}];

const data = $input.first().json;
const hits = data.hits || [];
const filter = $('V3: Smart Filter Score & Rank').first()?.json || {};
const fallback = $('V3: Fallback Router').first()?.json || {};
const rejected = fallback.rejectedTitles || filter.rejectedTitles || [];
const items = hits.slice(0, 12).map(h => ({
  title: h.title || h.story_title || '',
  link: h.url || h.story_url || '',
  summary: (h.story_text || h.comment_text || '').slice(0, 500),
  points: h.points || 0,
  source: 'news.ycombinator.com',
  ageHours: h.created_at_i ? (Date.now()/1000 - h.created_at_i)/3600 : 999
})).filter(x => x.title && x.link && x.ageHours < 48);

return [{ json: {
  researchItems: items,
  rejectedTitles: rejected,
  researchQuery: 'AI security LLM agents developer news',
  itemCount: items.length
}}];

