const resp = $input.first().json;
let text = resp.text || resp.output || '';
if (resp.candidates?.[0]?.content?.parts?.[0]?.text) text = resp.candidates[0].content.parts[0].text;
const article = $('V3: Merge Image Pipeline').first().json;

function clean(t) {
  return String(t)
    .replace(/\*\*(.*?)\*\*/g, '$1').replace(/\*(.*?)\*/g, '$1')
    .replace(/__(.*?)__/g, '$1').replace(/_(.*?)_/g, '$1')
    .replace(/^#+\s*/gm, '').replace(/^\s*[-*]\s+/gm, '• ')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1: $2').replace(/\n{3,}/g, '\n\n').trim();
}

const telegramPostText = clean(text);
const linkLine = article.link ? `\n\nRead more: ${article.link}` : '';
const caption = (telegramPostText + linkLine).slice(0, 1024);

const staticData = $getWorkflowStaticData('global');
if (!staticData.postedUrls) staticData.postedUrls = [];
if (!staticData.postedTitles) staticData.postedTitles = [];
if (!staticData.analytics) staticData.analytics = [];
if (article.link && !staticData.postedUrls.includes(article.link)) {
  staticData.postedUrls.push(article.link);
  if (staticData.postedUrls.length > 300) staticData.postedUrls = staticData.postedUrls.slice(-300);
}
if (article.title && !staticData.postedTitles.includes(article.title)) {
  staticData.postedTitles.push(article.title);
  if (staticData.postedTitles.length > 300) staticData.postedTitles = staticData.postedTitles.slice(-300);
}

return [{ json: { ...article, telegramPostText: caption, hasImage: !!article.imageUrl } }];

